name: NSIR Core CI Pipeline
on:
  push:
    branches: [main, develop]
  pull_request:
    branches: [main]
env:
  PROOF_TIMEOUT: 300
  ZIG_VERSION: "0.13.0"
  FUTHARK_VERSION: "0.25.0"
jobs:
  check-todos:
    name: Check for TODO markers
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Check for TODO markers
        run: |
          if grep -rn --include="*.zig" --include="*.agda" --include="*.lean" \
              --include="*.v" --include="*.tcl" --include="*.fut" --include="*.tla" \
              --include="*.pml" --include="*.vpr" --include="*.thy" --include="*.py" \
              -E 'TODO|FIXME|XXX|HACK' . | grep -v ".git" | grep -v "ci/"; then
            echo "ERROR: Found TODO markers in source files"
            exit 1
          fi
          echo "No TODO markers found"
  verify-agda:
    name: Agda Verification
    runs-on: ubuntu-latest
    needs: check-todos
    steps:
      - uses: actions/checkout@v4
      - name: Install Agda
        run: |
          sudo apt-get update
          sudo apt-get install -y agda agda-stdlib
      - name: Verify Agda proofs
        run: |
          cd verification/agda
          for file in *.agda; do
            if [ "$file" != "Prelude.agda" ]; then
              echo "Checking $file..."
              timeout $PROOF_TIMEOUT agda --safe --without-K "$file" || exit 1
            fi
          done
  verify-lean:
    name: Lean4 Verification
    runs-on: ubuntu-latest
    needs: check-todos
    steps:
      - uses: actions/checkout@v4
      - name: Install Lean4
        run: |
          curl  -sSf | sh -s -- -y
          echo "$HOME/.elan/bin" >> $GITHUB_PATH
      - name: Build Lean project
        run: |
          cd verification/lean
          lake update
          timeout $PROOF_TIMEOUT lake build
  verify-tla:
    name: TLA+ Verification
    runs-on: ubuntu-latest
    needs: check-todos
    steps:
      - uses: actions/checkout@v4
      - name: Install TLA+ tools
        run: |
          wget 
          unzip -q TLAToolbox-1.8.0-linux.gtk.x86_64.zip
          echo "TLA tools installed"
      - name: Check TLA+ specs
        run: |
          cd verification/tla
          for spec in *.tla; do
            echo "Checking $spec for deadlocks..."
            java -cp $TLA_PATH tlc2.TLC "$spec"
          done
  build-zig:
    name: Build Zig Core
    runs-on: ubuntu-latest
    needs: [verify-agda, verify-lean]
    steps:
      - uses: actions/checkout@v4
      - name: Install Zig
        uses: goto-bus-stop/setup-zig@v2
        with:
          version: ${{ env.ZIG_VERSION }}
      - name: Build
        run: |
          cd core/zig
          zig build -Doptimize=ReleaseSafe
      - name: Test
        run: |
          cd core/zig
          zig build test
      - name: Upload artifacts
        uses: actions/upload-artifact@v4
        with:
          name: zig-build
          path: core/zig/zig-out/
  build-futhark:
    name: Build Futhark Kernels
    runs-on: ubuntu-latest
    needs: check-todos
    steps:
      - uses: actions/checkout@v4
      - name: Install Futhark
        run: |
          wget  env.FUTHARK_VERSION }}/futhark-${{ env.FUTHARK_VERSION }}-linux-x86_64.tar.xz
          tar xf futhark-${{ env.FUTHARK_VERSION }}-linux-x86_64.tar.xz
          sudo mv futhark-${{ env.FUTHARK_VERSION }}/bin/futhark /usr/local/bin/
      - name: Build C backend
        run: |
          cd kernels
          futhark c distributed.fut -o distributed
      - name: Upload artifacts
        uses: actions/upload-artifact@v4
        with:
          name: futhark-build
          path: kernels/distributed
  generate-hardware:
    name: Generate Hardware Artifacts
    runs-on: ubuntu-latest
    needs: check-todos
    steps:
      - uses: actions/checkout@v4
      - name: Run ASIC floorplan
        run: |
          cd hardware/asic
          tclsh floorplan.tcl
      - name: Prepare FPGA synthesis
        run: |
          cd hardware/fpga
          echo "FPGA files ready for synthesis"
          ls -la
  integration-test:
    name: Integration Tests
    runs-on: ubuntu-latest
    needs: [build-zig, build-futhark]
    steps:
      - uses: actions/checkout@v4
      - name: Download Zig build
        uses: actions/download-artifact@v4
        with:
          name: zig-build
          path: core/zig/zig-out/
      - name: Run integration tests
        run: |
          python3 scripts/check_proofs_all.py --dry-run
  dataset-validation:
    name: Validate Training Data
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Generate and validate dataset
        env:
          STRICTMODE: "1"
        run: |
          python3 scripts/generate_hungarian_qa.py --num-pairs 200
          python3 scripts/generate_hungarian_qa.py --validate-only
  all-checks:
    name: All Checks Passed
    runs-on: ubuntu-latest
    needs: [integration-test, generate-hardware, dataset-validation]
    steps:
      - run: echo "All checks passed!"
