const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const lib = b.addStaticLibrary(.{
        .name = "nsir_core",
        .root_source_file = b.path("nsir_core.zig"),
        .target = target,
        .optimize = optimize,
    });

    lib.linkLibC();

    b.installArtifact(lib);

    const shared_lib = b.addSharedLibrary(.{
        .name = "nsir_core",
        .root_source_file = b.path("nsir_core.zig"),
        .target = target,
        .optimize = optimize,
    });

    shared_lib.linkLibC();

    b.installArtifact(shared_lib);

    const exe = b.addExecutable(.{
        .name = "nsir_cli",
        .root_source_file = b.path("main.zig"),
        .target = target,
        .optimize = optimize,
    });

    exe.linkLibC();

    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());

    if (b.args) |args| {
        run_cmd.addArgs(args);
    }

    const run_step = b.step("run", "Run the CLI");
    run_step.dependOn(&run_cmd.step);

    const unit_tests = b.addTest(.{
        .root_source_file = b.path("nsir_core.zig"),
        .target = target,
        .optimize = optimize,
    });

    unit_tests.linkLibC();

    const run_unit_tests = b.addRunArtifact(unit_tests);

    const io_tests = b.addTest(.{
        .root_source_file = b.path("io.zig"),
        .target = target,
        .optimize = optimize,
    });

    io_tests.linkLibC();

    const run_io_tests = b.addRunArtifact(io_tests);

    const hash_tests = b.addTest(.{
        .root_source_file = b.path("hash.zig"),
        .target = target,
        .optimize = optimize,
    });

    const run_hash_tests = b.addRunArtifact(hash_tests);

    const crev_tests = b.addTest(.{
        .root_source_file = b.path("crev_pipeline.zig"),
        .target = target,
        .optimize = optimize,
    });

    crev_tests.linkLibC();

    const run_crev_tests = b.addRunArtifact(crev_tests);

    const optimizer_tests = b.addTest(.{
        .root_source_file = b.path("optimizer.zig"),
        .target = target,
        .optimize = optimize,
    });

    const run_optimizer_tests = b.addRunArtifact(optimizer_tests);

    const test_step = b.step("test", "Run unit tests");
    test_step.dependOn(&run_unit_tests.step);
    test_step.dependOn(&run_io_tests.step);
    test_step.dependOn(&run_hash_tests.step);
    test_step.dependOn(&run_crev_tests.step);
    test_step.dependOn(&run_optimizer_tests.step);

    const docs = b.addInstallDirectory(.{
        .source_dir = lib.getEmittedDocs(),
        .install_dir = .prefix,
        .install_subdir = "docs",
    });

    const docs_step = b.step("docs", "Generate documentation");
    docs_step.dependOn(&docs.step);
}
