```zig
const std = @import("std");
const capi = @import("capi.zig");
const optimizer = @import("optimizer.zig");
const hash = @import("hash.zig");

pub const Complex = struct {
    real: f64,
    imag: f64,

    pub fn init(real: f64, imag: f64) Complex {
        return .{ .real = real, .imag = imag };
    }

    pub fn magnitude(self: Complex) f64 {
        return @sqrt(self.real * self.real + self.imag * self.imag);
    }

    pub fn phase(self: Complex) f64 {
        return std.math.atan2(self.imag, self.real);
    }

    pub fn multiply(self: Complex, other: Complex) Complex {
        return .{
            .real = self.real * other.real - self.imag * other.imag,
            .imag = self.real * other.imag + self.imag * other.real,
        };
    }

    pub fn add(self: Complex, other: Complex) Complex {
        return .{
            .real = self.real + other.real,
            .imag = self.imag + other.imag,
        };
    }

    pub fn conjugate(self: Complex) Complex {
        return .{ .real = self.real, .imag = -self.imag };
    }

    pub fn normalize(self: Complex) Complex {
        const mag = self.magnitude();
        if (mag == 0) return .{ .real = 1.0, .imag = 0.0 };
        return .{ .real = self.real / mag, .imag = self.imag / mag };
    }

    pub fn rotate(self: Complex, angle: f64) Complex {
        const cos_a = @cos(angle);
        const sin_a = @sin(angle);
        return .{
            .real = self.real * cos_a - self.imag * sin_a,
            .imag = self.real * sin_a + self.imag * cos_a,
        };
    }
};

pub const EdgeQuality = enum(u8) {
    superposition = 0,
    entangled = 1,
    coherent = 2,
    collapsed = 3,
    fractal = 4,

    pub fn fromInt(val: u8) ?EdgeQuality {
        return switch (val) {
            0 => .superposition,
            1 => .entangled,
            2 => .coherent,
            3 => .collapsed,
            4 => .fractal,
            else => null,
        };
    }
};

pub const Node = struct {
    id: u64,
    type_name: []const u8,
    quantum_state: Complex,
    phase_param: f64,
    metadata: ?*anyopaque,

    pub fn init(id: u64, type_name: []const u8) Node {
        return .{
            .id = id,
            .type_name = type_name,
            .quantum_state = Complex.init(1.0, 0.0),
            .phase_param = 0.0,
            .metadata = null,
        };
    }

    pub fn setQuantumState(self: *Node, state: Complex) void {
        self.quantum_state = state;
    }

    pub fn rotatePhase(self: *Node, angle: f64) void {
        self.quantum_state = self.quantum_state.rotate(angle);
        self.phase_param = @mod(self.phase_param + angle, 2.0 * std.math.pi);
    }

    pub fn collapse(self: *Node) void {
        self.quantum_state = self.quantum_state.normalize();
    }
};

pub const Edge = struct {
    source_id: u64,
    target_id: u64,
    weight: f64,
    quality: EdgeQuality,
    fractal_dimension: f64,
    quantum_correlation: Complex,

    pub fn init(source_id: u64, target_id: u64, weight: f64) Edge {
        return .{
            .source_id = source_id,
            .target_id = target_id,
            .weight = weight,
            .quality = .superposition,
            .fractal_dimension = 1.0,
            .quantum_correlation = Complex.init(1.0, 0.0),
        };
    }

    pub fn entangle(self: *Edge, correlation: Complex) void {
        self.quantum_correlation = correlation.normalize();
        self.quality = .entangled;
    }

    pub fn setFractalDimension(self: *Edge, dim: f64) void {
        self.fractal_dimension = @max(1.0, @min(3.0, dim));
        if (dim > 1.5) {
            self.quality = .fractal;
        }
    }
};

pub const Graph = struct {
    allocator: std.mem.Allocator,
    nodes: std.AutoHashMap(u64, Node),
    edges: std.ArrayList(Edge),
    next_node_id: u64,
    type_name_storage: std.ArrayList([]u8),

    pub fn init(allocator: std.mem.Allocator) Graph {
        return .{
            .allocator = allocator,
            .nodes = std.AutoHashMap(u64, Node).init(allocator),
            .edges = std.ArrayList(Edge).init(allocator),
            .next_node_id = 1,
            .type_name_storage = std.ArrayList([]u8).init(allocator),
        };
    }

    pub fn deinit(self: *Graph) void {
        for (self.type_name_storage.items) |name| {
            self.allocator.free(name);
        }
        self.type_name_storage.deinit();
        self.nodes.deinit();
        self.edges.deinit();
    }

    pub fn addNode(self: *Graph, type_name: []const u8) !u64 {
        const id = self.next_node_id;
        self.next_node_id += 1;

        const owned_name = try self.allocator.dupe(u8, type_name);
        try self.type_name_storage.append(owned_name);

        const node = Node.init(id, owned_name);
        try self.nodes.put(id, node);

        return id;
    }

    pub fn getNode(self: *Graph, id: u64) ?*Node {
        return self.nodes.getPtr(id);
    }

    pub fn addEdge(self: *Graph, source_id: u64, target_id: u64, weight: f64) !void {
        if (!self.nodes.contains(source_id) or !self.nodes.contains(target_id)) {
            return error.NodeNotFound;
        }

        const edge = Edge.init(source_id, target_id, weight);
        try self.edges.append(edge);
    }

    pub fn entangleNodes(self: *Graph, id1: u64, id2: u64) !void {
        const node1 = self.getNode(id1) orelse return error.NodeNotFound;
        const node2 = self.getNode(id2) orelse return error.NodeNotFound;

        const correlation = node1.quantum_state.multiply(node2.quantum_state.conjugate());

        try self.addEdge(id1, id2, 1.0);

        if (self.edges.items.len > 0) {
            self.edges.items[self.edges.items.len - 1].entangle(correlation);
        }

        node1.quantum_state = node1.quantum_state.normalize();
        node2.quantum_state = correlation.normalize();
    }

    pub fn computeTotalEnergy(self: *Graph) f64 {
        var energy: f64 = 0.0;

        for (self.edges.items) |edge| {
            energy += edge.weight * edge.fractal_dimension;
            energy += edge.quantum_correlation.magnitude();
        }

        var node_iter = self.nodes.valueIterator();
        while (node_iter.next()) |node| {
            energy += node.quantum_state.magnitude();
        }

        return energy;
    }

    pub fn nodeCount(self: *const Graph) usize {
        return self.nodes.count();
    }

    pub fn edgeCount(self: *const Graph) usize {
        return self.edges.items.len;
    }
};

pub const GraphOptimizer = optimizer.EntangledSymmetryOptimizer;

test "Complex number operations" {
    const c1 = Complex.init(3.0, 4.0);
    try std.testing.expectApproxEqAbs(@as(f64, 5.0), c1.magnitude(), 0.0001);

    const c2 = Complex.init(1.0, 2.0);
    const product = c1.multiply(c2);
    try std.testing.expectApproxEqAbs(@as(f64, -5.0), product.real, 0.0001);
    try std.testing.expectApproxEqAbs(@as(f64, 10.0), product.imag, 0.0001);

    const rotated = c1.rotate(std.math.pi / 2.0);
    try std.testing.expectApproxEqAbs(@as(f64, -4.0), rotated.real, 0.0001);
    try std.testing.expectApproxEqAbs(@as(f64, 3.0), rotated.imag, 0.0001);
}

test "Node creation and manipulation" {
    var node = Node.init(1, "test_node");
    try std.testing.expectEqual(@as(u64, 1), node.id);
    try std.testing.expectApproxEqAbs(@as(f64, 1.0), node.quantum_state.magnitude(), 0.0001);

    node.rotatePhase(std.math.pi / 4.0);
    try std.testing.expectApproxEqAbs(@as(f64, 1.0), node.quantum_state.magnitude(), 0.0001);
}

test "Edge quality ordering" {
    try std.testing.expectEqual(@as(u8, 0), @intFromEnum(EdgeQuality.superposition));
    try std.testing.expectEqual(@as(u8, 1), @intFromEnum(EdgeQuality.entangled));
    try std.testing.expectEqual(@as(u8, 2), @intFromEnum(EdgeQuality.coherent));
    try std.testing.expectEqual(@as(u8, 3), @intFromEnum(EdgeQuality.collapsed));
    try std.testing.expectEqual(@as(u8, 4), @intFromEnum(EdgeQuality.fractal));
}

test "Graph operations" {
    const allocator = std.testing.allocator;
    var graph = Graph.init(allocator);
    defer graph.deinit();

    const id1 = try graph.addNode("node_a");
    const id2 = try graph.addNode("node_b");

    try std.testing.expectEqual(@as(usize, 2), graph.nodeCount());

    try graph.addEdge(id1, id2, 0.5);
    try std.testing.expectEqual(@as(usize, 1), graph.edgeCount());

    try graph.entangleNodes(id1, id2);
    try std.testing.expectEqual(@as(usize, 2), graph.edgeCount());
}
