## ./core/zig/capi.zig
```zig
const std = @import("std");
const core = @import("nsir_core.zig");
const optimizer = @import("optimizer.zig");

pub const CComplex = extern struct {
    real: f64,
    imag: f64,
};

pub const CNode = extern struct {
    id: u64,
    type_name: [*:0]const u8,
    quantum_state: CComplex,
    phase_param: f64,
};

pub const CEdge = extern struct {
    source_id: u64,
    target_id: u64,
    weight: f64,
    quality: u8,
    fractal_dimension: f64,
    quantum_correlation: CComplex,
};

pub const COptimizationStats = extern struct {
    iterations_completed: u64,
    moves_accepted: u64,
    best_energy: f64,
    temperature: f64,
    acceptance_rate: f64,
};

pub const CGraphHandle = *anyopaque;

var global_allocator: std.mem.Allocator = std.heap.page_allocator;

const GraphWrapper = struct {
    graph: core.Graph,
    optimizer: ?optimizer.EntangledSymmetryOptimizer,

    fn init(allocator: std.mem.Allocator) GraphWrapper {
        return .{
            .graph = core.Graph.init(allocator),
            .optimizer = null,
        };
    }

    fn deinit(self: *GraphWrapper) void {
        self.graph.deinit();
    }
};

export fn nsir_create_graph() callconv(.C) ?CGraphHandle {
    const wrapper = global_allocator.create(GraphWrapper) catch return null;
    wrapper.* = GraphWrapper.init(global_allocator);
    return @ptrCast(wrapper);
}

export fn nsir_destroy_graph(handle: ?CGraphHandle) callconv(.C) void {
    if (handle) |h| {
        const wrapper: *GraphWrapper = @ptrCast(@alignCast(h));
        wrapper.deinit();
        global_allocator.destroy(wrapper);
    }
}

export fn nsir_add_node(handle: ?CGraphHandle, type_name: ?[*:0]const u8) callconv(.C) u64 {
    if (handle == null or type_name == null) return 0;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));
    const name_slice = std.mem.span(type_name.?);

    if (name_slice.len == 0 or name_slice.len > 256) return 0;

    for (name_slice) |c| {
        if (c < 32 or c > 126) return 0;
    }

    const id = wrapper.graph.addNode(name_slice) catch return 0;
    return id;
}

export fn nsir_get_node(handle: ?CGraphHandle, id: u64, out_node: ?*CNode) callconv(.C) bool {
    if (handle == null or out_node == null) return false;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));
    const node = wrapper.graph.getNode(id) orelse return false;

    out_node.?.* = .{
        .id = node.id,
        .type_name = @ptrCast(node.type_name.ptr),
        .quantum_state = .{
            .real = node.quantum_state.real,
            .imag = node.quantum_state.imag,
        },
        .phase_param = node.phase_param,
    };

    return true;
}

export fn nsir_set_quantum_state(handle: ?CGraphHandle, id: u64, real: f64, imag: f64) callconv(.C) bool {
    if (handle == null) return false;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));
    const node = wrapper.graph.getNode(id) orelse return false;

    node.setQuantumState(core.Complex.init(real, imag));
    return true;
}

export fn nsir_add_edge(handle: ?CGraphHandle, source_id: u64, target_id: u64, weight: f64) callconv(.C) bool {
    if (handle == null) return false;
    if (weight < -1e10 or weight > 1e10) return false;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));
    wrapper.graph.addEdge(source_id, target_id, weight) catch return false;
    return true;
}

export fn nsir_entangle_nodes(handle: ?CGraphHandle, id1: u64, id2: u64) callconv(.C) bool {
    if (handle == null) return false;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));
    wrapper.graph.entangleNodes(id1, id2) catch return false;
    return true;
}

export fn nsir_init_optimizer(handle: ?CGraphHandle, temperature: f64, cooling_rate: f64) callconv(.C) bool {
    if (handle == null) return false;
    if (temperature <= 0 or cooling_rate <= 0 or cooling_rate >= 1) return false;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));
    wrapper.optimizer = optimizer.EntangledSymmetryOptimizer.init(temperature, cooling_rate, null);
    return true;
}

export fn nsir_init_optimizer_seeded(handle: ?CGraphHandle, temperature: f64, cooling_rate: f64, seed: u64) callconv(.C) bool {
    if (handle == null) return false;
    if (temperature <= 0 or cooling_rate <= 0 or cooling_rate >= 1) return false;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));
    wrapper.optimizer = optimizer.EntangledSymmetryOptimizer.init(temperature, cooling_rate, seed);
    return true;
}

export fn nsir_optimize(handle: ?CGraphHandle, iterations: u64, out_stats: ?*COptimizationStats) callconv(.C) bool {
    if (handle == null) return false;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));

    if (wrapper.optimizer == null) {
        wrapper.optimizer = optimizer.EntangledSymmetryOptimizer.init(100.0, 0.995, null);
    }

    var opt = &wrapper.optimizer.?;

    opt.optimize(&wrapper.graph, iterations);

    if (out_stats) |stats| {
        const opt_stats = opt.getStats();
        stats.* = .{
            .iterations_completed = opt_stats.iterations_completed,
            .moves_accepted = opt_stats.moves_accepted,
            .best_energy = opt_stats.best_energy,
            .temperature = opt_stats.temperature,
            .acceptance_rate = opt_stats.acceptance_rate,
        };
    }

    return true;
}

export fn nsir_get_energy(handle: ?CGraphHandle) callconv(.C) f64 {
    if (handle == null) return -1.0;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));
    return wrapper.graph.computeTotalEnergy();
}

export fn nsir_node_count(handle: ?CGraphHandle) callconv(.C) u64 {
    if (handle == null) return 0;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));
    return @intCast(wrapper.graph.nodeCount());
}

export fn nsir_edge_count(handle: ?CGraphHandle) callconv(.C) u64 {
    if (handle == null) return 0;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));
    return @intCast(wrapper.graph.edgeCount());
}

export fn nsir_get_edge(handle: ?CGraphHandle, index: u64, out_edge: ?*CEdge) callconv(.C) bool {
    if (handle == null or out_edge == null) return false;

    const wrapper: *GraphWrapper = @ptrCast(@alignCast(handle.?));

    if (index >= wrapper.graph.edges.items.len) return false;

    const edge = wrapper.graph.edges.items[index];
    out_edge.?.* = .{
        .source_id = edge.source_id,
        .target_id = edge.target_id,
        .weight = edge.weight,
        .quality = @intFromEnum(edge.quality),
        .fractal_dimension = edge.fractal_dimension,
        .quantum_correlation = .{
            .real = edge.quantum_correlation.real,
            .imag = edge.quantum_correlation.imag,
        },
    };

    return true;
}

export fn nsir_version() callconv(.C) u32 {
    return 0x00010000;
}

