const std = @import("std");
const core = @import("nsir_core.zig");
const hash = @import("hash.zig");

pub const OptimizationStats = struct {
    iterations_completed: u64,
    moves_accepted: u64,
    best_energy: f64,
    temperature: f64,
    acceptance_rate: f64,
};

pub const EntangledSymmetryOptimizer = struct {
    temperature: f64,
    cooling_rate: f64,
    current_energy: f64,
    best_energy: f64,
    acceptance_rate: f64,
    iterations_completed: u64,
    moves_accepted: u64,
    prng: std.Random.Xoshiro256,

    const EDGE_PERTURBATION_PROBABILITY: f64 = 0.3;
    const NODE_PHASE_PROBABILITY: f64 = 0.2;
    const HIGH_ACCEPTANCE_THRESHOLD: f64 = 0.6;
    const LOW_ACCEPTANCE_THRESHOLD: f64 = 0.2;
    const ACCELERATE_FACTOR: f64 = 0.98;
    const DECELERATE_FACTOR: f64 = 1.02;

    pub fn init(temperature: f64, cooling_rate: f64, seed: ?u64) EntangledSymmetryOptimizer {
        const actual_seed = seed orelse hash.generateRuntimeSeed();
        return .{
            .temperature = temperature,
            .cooling_rate = cooling_rate,
            .current_energy = std.math.inf(f64),
            .best_energy = std.math.inf(f64),
            .acceptance_rate = 0.5,
            .iterations_completed = 0,
            .moves_accepted = 0,
            .prng = std.Random.Xoshiro256.init(actual_seed),
        };
    }

    pub fn computeEnergy(self: *EntangledSymmetryOptimizer, graph: *core.Graph) f64 {
        _ = self;
        var energy: f64 = 0.0;

        for (graph.edges.items) |edge| {
            energy += edge.weight * edge.fractal_dimension;
            energy += edge.quantum_correlation.magnitude();
        }

        var node_iter = graph.nodes.valueIterator();
        while (node_iter.next()) |node| {
            energy += node.quantum_state.magnitude();
        }

        return energy;
    }

    pub fn perturbGraph(self: *EntangledSymmetryOptimizer, graph: *core.Graph) void {
        const random = self.prng.random();

        for (graph.edges.items) |*edge| {
            if (random.float(f64) < EDGE_PERTURBATION_PROBABILITY) {
                const perturbation = (random.float(f64) - 0.5) * 2.0 * self.temperature * 0.01;
                edge.weight = @max(-1e10, @min(1e10, edge.weight + perturbation));
            }
        }

        var node_iter = graph.nodes.valueIterator();
        while (node_iter.next()) |node| {
            if (random.float(f64) < NODE_PHASE_PROBABILITY) {
                const angle = (random.float(f64) - 0.5) * self.temperature * 0.01;
                node.rotatePhase(angle);
            }
        }
    }

    fn saveState(self: *EntangledSymmetryOptimizer, graph: *core.Graph, allocator: std.mem.Allocator) !GraphState {
        _ = self;
        var state = GraphState{
            .edge_weights = try allocator.alloc(f64, graph.edges.items.len),
            .node_states = std.AutoHashMap(u64, NodeState).init(allocator),
        };

        for (graph.edges.items, 0..) |edge, i| {
            state.edge_weights[i] = edge.weight;
        }

        var node_iter = graph.nodes.iterator();
        while (node_iter.next()) |entry| {
            try state.node_states.put(entry.key_ptr.*, .{
                .quantum_state = entry.value_ptr.quantum_state,
                .phase_param = entry.value_ptr.phase_param,
            });
        }

        return state;
    }

    fn restoreState(self: *EntangledSymmetryOptimizer, graph: *core.Graph, state: *const GraphState) void {
        _ = self;
        for (graph.edges.items, 0..) |*edge, i| {
            if (i < state.edge_weights.len) {
                edge.weight = state.edge_weights[i];
            }
        }

        var node_iter = graph.nodes.valueIterator();
        while (node_iter.next()) |node| {
            if (state.node_states.get(node.id)) |saved| {
                node.quantum_state = saved.quantum_state;
                node.phase_param = saved.phase_param;
            }
        }
    }

    fn freeState(state: *GraphState, allocator: std.mem.Allocator) void {
        allocator.free(state.edge_weights);
        state.node_states.deinit();
    }

    pub fn optimize(self: *EntangledSymmetryOptimizer, graph: *core.Graph, iterations: u64) void {
        if (self.current_energy == std.math.inf(f64)) {
            self.current_energy = self.computeEnergy(graph);
            self.best_energy = self.current_energy;
        }

        var accepted_in_window: u64 = 0;
        const window_size: u64 = @max(1, iterations / 10);

        var i: u64 = 0;
        while (i < iterations) : (i += 1) {
            const state = self.saveState(graph, std.heap.page_allocator) catch continue;
            defer {
                var mutable_state = state;
                freeState(&mutable_state, std.heap.page_allocator);
            }

            self.perturbGraph(graph);

            const new_energy = self.computeEnergy(graph);
            const delta = new_energy - self.current_energy;

            const accept = if (delta < 0)
                true
            else
                self.prng.random().float(f64) < @exp(-delta / self.temperature);

            if (accept) {
                self.current_energy = new_energy;
                self.moves_accepted += 1;
                accepted_in_window += 1;

                if (new_energy < self.best_energy) {
                    self.best_energy = new_energy;
                }
            } else {
                self.restoreState(graph, &state);
            }

            self.iterations_completed += 1;

            if ((i + 1) % window_size == 0 and window_size > 0) {
                self.acceptance_rate = @as(f64, @floatFromInt(accepted_in_window)) / @as(f64, @floatFromInt(window_size));
                accepted_in_window = 0;

                self.adaptCooling();
            }

            self.temperature *= self.cooling_rate;
        }
    }

    fn adaptCooling(self: *EntangledSymmetryOptimizer) void {
        if (self.acceptance_rate > HIGH_ACCEPTANCE_THRESHOLD) {
            self.cooling_rate *= ACCELERATE_FACTOR;
            self.cooling_rate = @max(0.9, self.cooling_rate);
        } else if (self.acceptance_rate < LOW_ACCEPTANCE_THRESHOLD) {
            self.cooling_rate *= DECELERATE_FACTOR;
            self.cooling_rate = @min(0.999, self.cooling_rate);
        }
    }

    pub fn getStats(self: *const EntangledSymmetryOptimizer) OptimizationStats {
        return .{
            .iterations_completed = self.iterations_completed,
            .moves_accepted = self.moves_accepted,
            .best_energy = self.best_energy,
            .temperature = self.temperature,
            .acceptance_rate = self.acceptance_rate,
        };
    }

    pub fn reset(self: *EntangledSymmetryOptimizer, temperature: f64) void {
        self.temperature = temperature;
        self.current_energy = std.math.inf(f64);
        self.best_energy = std.math.inf(f64);
        self.acceptance_rate = 0.5;
        self.iterations_completed = 0;
        self.moves_accepted = 0;
    }
};

const GraphState = struct {
    edge_weights: []f64,
    node_states: std.AutoHashMap(u64, NodeState),
};

const NodeState = struct {
    quantum_state: core.Complex,
    phase_param: f64,
};

test "Optimizer initialization" {
    var opt = EntangledSymmetryOptimizer.init(100.0, 0.995, 12345);
    try std.testing.expectApproxEqAbs(@as(f64, 100.0), opt.temperature, 0.0001);
    try std.testing.expectApproxEqAbs(@as(f64, 0.995), opt.cooling_rate, 0.0001);
    try std.testing.expectEqual(@as(u64, 0), opt.iterations_completed);
}

test "Optimizer energy computation" {
    const allocator = std.testing.allocator;
    var graph = core.Graph.init(allocator);
    defer graph.deinit();

    const id1 = try graph.addNode("a");
    const id2 = try graph.addNode("b");
    try graph.addEdge(id1, id2, 1.0);

    var opt = EntangledSymmetryOptimizer.init(100.0, 0.995, 12345);
    const energy = opt.computeEnergy(&graph);
    try std.testing.expect(energy > 0);
}

test "Optimizer run" {
    const allocator = std.testing.allocator;
    var graph = core.Graph.init(allocator);
    defer graph.deinit();

    _ = try graph.addNode("a");
    _ = try graph.addNode("b");

    var opt = EntangledSymmetryOptimizer.init(100.0, 0.995, 12345);
    opt.optimize(&graph, 100);

    try std.testing.expectEqual(@as(u64, 100), opt.iterations_completed);
    try std.testing.expect(opt.moves_accepted > 0);
}

test "Adaptive cooling" {
    var opt = EntangledSymmetryOptimizer.init(100.0, 0.995, 12345);

    opt.acceptance_rate = 0.7;
    opt.adaptCooling();
    try std.testing.expect(opt.cooling_rate < 0.995);

    opt.cooling_rate = 0.995;
    opt.acceptance_rate = 0.1;
    opt.adaptCooling();
    try std.testing.expect(opt.cooling_rate > 0.995);
}
