const std = @import("std");

pub const WYHASH_SECRET0: u64 = 0xa0761d6478bd642f;
pub const WYHASH_SECRET1: u64 = 0xe7037ed1a0b428db;
pub const WYHASH_SECRET2: u64 = 0x8ebc6af09c88c6e3;
pub const WYHASH_SECRET3: u64 = 0x589965cc75374cc3;

fn wymix(a: u64, b: u64) u64 {
    const r = @as(u128, a) *% @as(u128, b);
    return @truncate(r ^ (r >> 64));
}

fn wyread8(data: []const u8) u64 {
    if (data.len < 8) return 0;
    return std.mem.readInt(u64, data[0..8], .little);
}

fn wyread4(data: []const u8) u64 {
    if (data.len < 4) return 0;
    return std.mem.readInt(u32, data[0..4], .little);
}

fn wyread3(data: []const u8, k: usize) u64 {
    if (k == 0) return 0;
    const val = (@as(u64, data[0]) << 16) |
        (@as(u64, data[k >> 1]) << 8) |
        @as(u64, data[k - 1]);
    return val;
}

pub fn hash64(data: []const u8, seed: u64) u64 {
    const len = data.len;
    var a: u64 = undefined;
    var b: u64 = undefined;
    var s = seed ^ WYHASH_SECRET0;

    if (len <= 16) {
        if (len >= 4) {
            a = (wyread4(data) << 32) | wyread4(data[((len >> 3) << 2)..]);
            const end_offset = len -% 4;
            const end_data = if (end_offset <= len) data[end_offset..] else data[0..];
            b = (wyread4(end_data) << 32) | wyread4(data[(len -% 4 -% ((len >> 3) << 2))..]);
        } else if (len > 0) {
            a = wyread3(data, len);
            b = 0;
        } else {
            a = 0;
            b = 0;
        }
    } else {
        var ptr: usize = 0;
        var remaining = len;

        if (len > 48) {
            var s1 = s;
            var s2 = s;

            while (remaining > 48) {
                s = wymix(wyread8(data[ptr..]) ^ WYHASH_SECRET1, wyread8(data[ptr + 8 ..]) ^ s);
                s1 = wymix(wyread8(data[ptr + 16 ..]) ^ WYHASH_SECRET2, wyread8(data[ptr + 24 ..]) ^ s1);
                s2 = wymix(wyread8(data[ptr + 32 ..]) ^ WYHASH_SECRET3, wyread8(data[ptr + 40 ..]) ^ s2);
                ptr += 48;
                remaining -= 48;
            }
            s ^= s1 ^ s2;
        }

        while (remaining > 16) {
            s = wymix(wyread8(data[ptr..]) ^ WYHASH_SECRET1, wyread8(data[ptr + 8 ..]) ^ s);
            ptr += 16;
            remaining -= 16;
        }

        a = wyread8(data[len - 16 ..]);
        b = wyread8(data[len - 8 ..]);
    }

    return wymix(WYHASH_SECRET1 ^ len, wymix(a ^ WYHASH_SECRET1, b ^ s));
}

pub fn stableHash(data: []const u8) u64 {
    return hash64(data, 0);
}

pub fn generateRuntimeSeed() u64 {
    const timestamp = @as(u64, @bitCast(std.time.nanoTimestamp()));

    var entropy_bytes: [8]u8 = undefined;
    std.crypto.random.bytes(&entropy_bytes);
    const entropy = std.mem.readInt(u64, &entropy_bytes, .little);

    const pid: u64 = blk: {
        if (@hasDecl(std.posix, "getpid")) {
            break :blk @as(u64, @intCast(std.posix.getpid()));
        } else {
            break :blk 0;
        }
    };

    return timestamp ^ (pid << 32) ^ entropy;
}

pub fn hashString(s: []const u8) u64 {
    return stableHash(s);
}

pub fn hashU64(value: u64) u64 {
    var buf: [8]u8 = undefined;
    std.mem.writeInt(u64, &buf, value, .little);
    return stableHash(&buf);
}

pub fn combineHashes(h1: u64, h2: u64) u64 {
    return wymix(h1 ^ WYHASH_SECRET0, h2 ^ WYHASH_SECRET1);
}

pub const Hasher = struct {
    state: u64,

    pub fn init(seed: u64) Hasher {
        return .{ .state = seed ^ WYHASH_SECRET0 };
    }

    pub fn update(self: *Hasher, data: []const u8) void {
        self.state = wymix(self.state, hash64(data, self.state));
    }

    pub fn updateU64(self: *Hasher, value: u64) void {
        self.state = wymix(self.state ^ WYHASH_SECRET1, value ^ WYHASH_SECRET2);
    }

    pub fn final(self: *const Hasher) u64 {
        return wymix(self.state ^ WYHASH_SECRET3, WYHASH_SECRET0);
    }
};

test "hash64 empty string" {
    const h = hash64("", 0);
    try std.testing.expect(h != 0);
}

test "hash64 deterministic" {
    const data = "hello world";
    const h1 = hash64(data, 0);
    const h2 = hash64(data, 0);
    try std.testing.expectEqual(h1, h2);
}

test "hash64 different seeds" {
    const data = "test data";
    const h1 = hash64(data, 0);
    const h2 = hash64(data, 12345);
    try std.testing.expect(h1 != h2);
}

test "stableHash consistency" {
    const data = "consistent hashing test";
    const h1 = stableHash(data);
    const h2 = stableHash(data);
    try std.testing.expectEqual(h1, h2);
}

test "generateRuntimeSeed variability" {
    const seed1 = generateRuntimeSeed();
    const seed2 = generateRuntimeSeed();
    try std.testing.expect(seed1 != seed2);
}

test "Hasher streaming" {
    var hasher = Hasher.init(0);
    hasher.update("hello ");
    hasher.update("world");
    const h1 = hasher.final();

    var hasher2 = Hasher.init(0);
    hasher2.update("hello ");
    hasher2.update("world");
    const h2 = hasher2.final();

    try std.testing.expectEqual(h1, h2);
}

test "combineHashes" {
    const h1 = stableHash("first");
    const h2 = stableHash("second");
    const combined = combineHashes(h1, h2);
    try std.testing.expect(combined != h1);
    try std.testing.expect(combined != h2);
}
