const std = @import("std");
const builtin = @import("builtin");

pub const BUFFER_SIZE: usize = 8192;
pub const MAX_READ_BYTES: usize = 100 * 1024 * 1024;
pub const MAX_LINE_LENGTH: usize = 65536;
pub const FILE_VERSION: u32 = 1;
pub const FILE_MAGIC: u32 = 0x4E534952;
pub const INDEX_MAGIC: u32 = 0x49445853;

pub const MMapError = error{
    OpenFailed,
    MapFailed,
    ExtendFailed,
    WriteFailed,
    LockFailed,
    InvalidFile,
};

pub const MMapBuffer = struct {
    fd: std.posix.fd_t,
    data: []align(std.mem.page_size) u8,
    len: usize,
    capacity: usize,
    writable: bool,

    pub fn open(path: []const u8, writable: bool) MMapError!MMapBuffer {
        const flags: std.posix.O = if (writable)
            .{ .ACCMODE = .RDWR, .CREAT = true }
        else
            .{ .ACCMODE = .RDONLY };

        const fd = std.posix.open(path, flags, 0o644) catch return MMapError.OpenFailed;
        errdefer std.posix.close(fd);

        const stat = std.posix.fstat(fd) catch return MMapError.OpenFailed;
        var file_size: usize = @intCast(stat.size);

        if (file_size == 0 and writable) {
            const page_size = std.mem.page_size;
            const zeros = std.mem.zeroes([4096]u8);

            _ = std.posix.pwrite(fd, &zeros, 0) catch return MMapError.WriteFailed;
            file_size = page_size;

            std.posix.ftruncate(fd, @intCast(page_size)) catch return MMapError.ExtendFailed;
        }

        if (file_size == 0) {
            return MMapBuffer{
                .fd = fd,
                .data = &[_]u8{},
                .len = 0,
                .capacity = 0,
                .writable = writable,
            };
        }

        const prot: u32 = if (writable) std.posix.PROT.READ | std.posix.PROT.WRITE else std.posix.PROT.READ;

        const mapped = std.posix.mmap(null, file_size, prot, .{ .TYPE = .SHARED }, fd, 0) catch return MMapError.MapFailed;

        return MMapBuffer{
            .fd = fd,
            .data = mapped,
            .len = file_size,
            .capacity = file_size,
            .writable = writable,
        };
    }

    pub fn close(self: *MMapBuffer) void {
        if (self.data.len > 0) {
            std.posix.munmap(self.data);
        }
        std.posix.close(self.fd);
        self.* = undefined;
    }

    pub fn extend(self: *MMapBuffer, new_size: usize) MMapError!void {
        if (!self.writable) return MMapError.WriteFailed;
        if (new_size <= self.capacity) return;

        const flock = std.posix.Flock.init(.WRITE);
        flock.lock(self.fd, .BLOCKING) catch return MMapError.LockFailed;
        defer flock.unlock(self.fd) catch {};

        if (self.data.len > 0) {
            std.posix.munmap(self.data);
        }

        std.posix.ftruncate(self.fd, @intCast(new_size)) catch return MMapError.ExtendFailed;

        const zeros = std.mem.zeroes([4096]u8);
        var offset = self.capacity;
        while (offset < new_size) {
            const write_size = @min(zeros.len, new_size - offset);
            _ = std.posix.pwrite(self.fd, zeros[0..write_size], @intCast(offset)) catch return MMapError.WriteFailed;
            offset += write_size;
        }

        const prot: u32 = std.posix.PROT.READ | std.posix.PROT.WRITE;
        const mapped = std.posix.mmap(null, new_size, prot, .{ .TYPE = .SHARED }, self.fd, 0) catch return MMapError.MapFailed;

        self.data = mapped;
        self.len = new_size;
        self.capacity = new_size;
    }

    pub fn sync(self: *MMapBuffer) void {
        if (self.data.len > 0) {
            std.posix.msync(self.data, .{ .SYNC = true }) catch {};
        }
    }
};

pub const DurableWriter = struct {
    fd: std.posix.fd_t,
    buffer: [BUFFER_SIZE]u8,
    buffer_pos: usize,
    sync_writes: bool,
    flush_depth: u32,

    const MAX_FLUSH_DEPTH: u32 = 10;

    pub fn init(path: []const u8, sync_writes: bool) !DurableWriter {
        var flags: std.posix.O = .{ .ACCMODE = .WRONLY, .CREAT = true, .TRUNC = true };

        if (sync_writes and builtin.os.tag != .windows) {
            flags.SYNC = true;
        }

        const fd = try std.posix.open(path, flags, 0o644);

        return DurableWriter{
            .fd = fd,
            .buffer = undefined,
            .buffer_pos = 0,
            .sync_writes = sync_writes,
            .flush_depth = 0,
        };
    }

    pub fn write(self: *DurableWriter, data: []const u8) !void {
        var remaining = data;

        while (remaining.len > 0) {
            const space = BUFFER_SIZE - self.buffer_pos;
            const copy_len = @min(space, remaining.len);

            @memcpy(self.buffer[self.buffer_pos..][0..copy_len], remaining[0..copy_len]);
            self.buffer_pos += copy_len;
            remaining = remaining[copy_len..];

            if (self.buffer_pos == BUFFER_SIZE) {
                try self.flush();
            }
        }
    }

    pub fn flush(self: *DurableWriter) !void {
        if (self.flush_depth >= MAX_FLUSH_DEPTH) {
            return error.FlushDepthExceeded;
        }

        self.flush_depth += 1;
        defer self.flush_depth -= 1;

        if (self.buffer_pos == 0) return;

        const written = std.posix.write(self.fd, self.buffer[0..self.buffer_pos]) catch |err| {
            return err;
        };

        if (written < self.buffer_pos) {
            const remaining = self.buffer_pos - written;
            std.mem.copyBackwards(u8, self.buffer[0..remaining], self.buffer[written..self.buffer_pos]);
            self.buffer_pos = remaining;
            return error.PartialWrite;
        }

        self.buffer_pos = 0;
    }

    pub fn close(self: *DurableWriter) void {
        self.flush() catch {};
        if (self.sync_writes) {
            std.posix.fsync(self.fd) catch {};
        }
        std.posix.close(self.fd);
    }
};

pub const BinaryFileHeader = extern struct {
    magic: u32,
    version: u32,
    flags: u32,
    reserved: u32,
    data_offset: u64,
    data_size: u64,
    checksum: u64,
};

pub fn writeFileHeader(writer: anytype, magic: u32, data_size: u64) !void {
    const header = BinaryFileHeader{
        .magic = magic,
        .version = FILE_VERSION,
        .flags = 0,
        .reserved = 0,
        .data_offset = @sizeOf(BinaryFileHeader),
        .data_size = data_size,
        .checksum = 0,
    };

    try writer.writeAll(std.mem.asBytes(&header));
}

pub fn readFileHeader(reader: anytype) !BinaryFileHeader {
    var header: BinaryFileHeader = undefined;
    const bytes_read = try reader.readAll(std.mem.asBytes(&header));

    if (bytes_read != @sizeOf(BinaryFileHeader)) {
        return error.InvalidHeader;
    }

    if (header.magic != FILE_MAGIC and header.magic != INDEX_MAGIC) {
        return error.InvalidMagic;
    }

    if (header.version > FILE_VERSION) {
        return error.UnsupportedVersion;
    }

    return header;
}

pub fn readLineAlloc(allocator: std.mem.Allocator, reader: anytype) !?[]u8 {
    var line = std.ArrayList(u8).init(allocator);
    errdefer line.deinit();

    while (true) {
        const byte = reader.readByte() catch |err| switch (err) {
            error.EndOfStream => {
                if (line.items.len == 0) return null;
                return try line.toOwnedSlice();
            },
            else => return err,
        };

        if (byte == '\n') {
            return try line.toOwnedSlice();
        }

        if (line.items.len >= MAX_LINE_LENGTH) {
            return error.LineTooLong;
        }

        try line.append(byte);
    }
}

test "MMapBuffer basic operations" {
    const test_path = "/tmp/mmap_test_file";

    {
