        defer writer.close();

        try writer.write("Hello, World!\n");
        try writer.write("Second line\n");
        try writer.flush();
    }

    const content = try std.fs.cwd().readFileAlloc(std.testing.allocator, test_path, MAX_READ_BYTES);
    defer std.testing.allocator.free(content);

    try std.testing.expectEqualStrings("Hello, World!\nSecond line\n", content);

    std.fs.cwd().deleteFile(test_path) catch {};
