        try std.testing.expectEqual(@as(u64, 1024), header.data_size);
    }

    std.fs.cwd().deleteFile(test_path) catch {};
}

test "Constants" {
    try std.testing.expectEqual(@as(usize, 8192), BUFFER_SIZE);
    try std.testing.expectEqual(@as(usize, 100 * 1024 * 1024), MAX_READ_BYTES);
    try std.testing.expectEqual(@as(usize, 65536), MAX_LINE_LENGTH);
    try std.testing.expectEqual(@as(u32, 1), FILE_VERSION);
}
