const std = @import("std");
const hash = @import("hash.zig");

pub const TrainingConfig = struct {
    world_size: u32,
    rank: u32,
    batch_size: u32,
    learning_rate: f32,
    epochs: u32,
    gradient_accumulation_steps: u32,
    checkpoint_interval: u32,
    deterministic: bool,
    seed: u64,
};

pub const DataSample = struct {
    input_ids: []const u32,
    attention_mask: []const u32,
    labels: []const u32,
};

pub const Dataset = struct {
    allocator: std.mem.Allocator,
    samples: std.ArrayList(DataSample),
    total_samples: usize,

    pub fn init(allocator: std.mem.Allocator) Dataset {
        return .{
            .allocator = allocator,
            .samples = std.ArrayList(DataSample).init(allocator),
            .total_samples = 0,
        };
    }

    pub fn deinit(self: *Dataset) void {
        for (self.samples.items) |sample| {
            self.allocator.free(sample.input_ids);
            self.allocator.free(sample.attention_mask);
            self.allocator.free(sample.labels);
        }
        self.samples.deinit();
    }

    pub fn baseSamplesPerRank(self: *const Dataset, world_size: u32) usize {
        return self.total_samples / world_size;
    }

    pub fn samplesForRank(self: *const Dataset, rank: u32, world_size: u32) usize {
        const base = self.baseSamplesPerRank(world_size);
        const remainder = self.total_samples % world_size;
        return if (rank < remainder) base + 1 else base;
    }
};

pub const GradientBuffer = struct {
    data: []f32,
    size: usize,
    accumulated_steps: u32,

    pub fn init(allocator: std.mem.Allocator, size: usize) !GradientBuffer {
        const data = try allocator.alloc(f32, size);
        @memset(data, 0);
        return .{
            .data = data,
            .size = size,
            .accumulated_steps = 0,
        };
    }

    pub fn deinit(self: *GradientBuffer, allocator: std.mem.Allocator) void {
        allocator.free(self.data);
    }

    pub fn accumulate(self: *GradientBuffer, gradients: []const f32) void {
        for (self.data, 0..) |*d, i| {
            if (i < gradients.len) {
                d.* += gradients[i];
            }
        }
        self.accumulated_steps += 1;
    }

    pub fn average(self: *GradientBuffer) void {
        if (self.accumulated_steps > 0) {
            const scale = 1.0 / @as(f32, @floatFromInt(self.accumulated_steps));
            for (self.data) |*d| {
                d.* *= scale;
            }
        }
    }

    pub fn reset(self: *GradientBuffer) void {
        @memset(self.data, 0);
        self.accumulated_steps = 0;
    }
};

pub const DistributedTrainer = struct {
    allocator: std.mem.Allocator,
    config: TrainingConfig,
    dataset: ?Dataset,
    gradient_buffer: ?GradientBuffer,
    current_epoch: u32,
    current_step: u64,
    total_loss: f64,
    samples_processed: u64,
    prng: std.Random.Xoshiro256,

    pub fn init(allocator: std.mem.Allocator, config: TrainingConfig) DistributedTrainer {
        return .{
            .allocator = allocator,
            .config = config,
            .dataset = null,
            .gradient_buffer = null,
            .current_epoch = 0,
            .current_step = 0,
            .total_loss = 0,
            .samples_processed = 0,
            .prng = std.Random.Xoshiro256.init(config.seed),
        };
    }

    pub fn deinit(self: *DistributedTrainer) void {
        if (self.dataset) |*ds| {
            ds.deinit();
        }
        if (self.gradient_buffer) |*gb| {
            gb.deinit(self.allocator);
        }
    }

    pub fn loadDataset(self: *DistributedTrainer, json_path: []const u8) !void {
        const file = std.fs.cwd().openFile(json_path, .{}) catch |err| {
            std.log.warn("Could not open dataset file: {}", .{err});
            self.dataset = Dataset.init(self.allocator);
            return;
        };
        defer file.close();

        var dataset = Dataset.init(self.allocator);

        const reader = file.reader();
        var line_buf: [65536]u8 = undefined;

        while (reader.readUntilDelimiter(&line_buf, '\n')) |line| {
            if (line.len == 0) continue;

            const input_ids = try self.allocator.alloc(u32, 128);
            @memset(input_ids, 0);

            const attention_mask = try self.allocator.alloc(u32, 128);
            @memset(attention_mask, 1);

            const labels = try self.allocator.alloc(u32, 128);
            @memset(labels, 0);

            try dataset.samples.append(.{
                .input_ids = input_ids,
                .attention_mask = attention_mask,
                .labels = labels,
            });

            dataset.total_samples += 1;
        } else |err| switch (err) {
            error.EndOfStream => {},
            else => return err,
        }

        self.dataset = dataset;

        const base_per_rank = dataset.baseSamplesPerRank(self.config.world_size);
        std.log.info("Loaded {} samples, {} per rank", .{ dataset.total_samples, base_per_rank });
    }

    pub fn initGradientBuffer(self: *DistributedTrainer, param_count: usize) !void {
        self.gradient_buffer = try GradientBuffer.init(self.allocator, param_count);
    }

    pub fn trainEpoch(self: *DistributedTrainer) !void {
        const dataset = self.dataset orelse return error.NoDataset;

        const samples_for_rank = dataset.samplesForRank(self.config.rank, self.config.world_size);
        const batches = samples_for_rank / self.config.batch_size;

        var batch_idx: usize = 0;
        while (batch_idx < batches) : (batch_idx += 1) {
            const loss = self.computeBatchLoss(batch_idx);
            self.total_loss += loss;
            self.samples_processed += self.config.batch_size;

            if (self.gradient_buffer) |*gb| {
                gb.accumulated_steps += 1;

                if (gb.accumulated_steps >= self.config.gradient_accumulation_steps) {
                    gb.average();
                    self.synchronizeGradients();
                    gb.reset();
                }
            }

            self.current_step += 1;
        }

        self.current_epoch += 1;
    }

    fn computeBatchLoss(self: *DistributedTrainer, batch_idx: usize) f64 {
        _ = batch_idx;
        const random = self.prng.random();
        return random.float(f64) * 2.0 + 0.5;
    }

    fn synchronizeGradients(self: *DistributedTrainer) void {
        _ = self;
    }

    pub fn getAverageLoss(self: *const DistributedTrainer) f64 {
        if (self.samples_processed == 0) return 0;
        return self.total_loss / @as(f64, @floatFromInt(self.samples_processed));
    }

    pub fn checkpoint(self: *const DistributedTrainer, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();

        const writer = file.writer();
        try writer.print("epoch={}\n", .{self.current_epoch});
        try writer.print("step={}\n", .{self.current_step});
        try writer.print("loss={d:.6}\n", .{self.getAverageLoss()});
        try writer.print("samples={}\n", .{self.samples_processed});
    }
};

