```verilog
module toplevel (
    input  wire        clk,
    input  wire        rst_n,

    input  wire [31:0] awaddr,
    input  wire        awvalid,
    output reg         awready,
    input  wire [31:0] wdata,
    input  wire [3:0]  wstrb,
    input  wire        wvalid,
    output reg         wready,
    output reg  [1:0]  bresp,
    output reg         bvalid,
    input  wire        bready,

    input  wire [31:0] araddr,
    input  wire        arvalid,
    output reg         arready,
    output reg  [31:0] rdata,
    output reg  [1:0]  rresp,
    output reg         rvalid,
    input  wire        rready,

    output wire        led,
    output wire        irq_out
);

localparam ADDR_CTRL        = 12'h000;
localparam ADDR_STATUS      = 12'h004;
localparam ADDR_VERSION     = 12'h008;
localparam ADDR_NODE_COUNT  = 12'h00C;
localparam ADDR_EDGE_COUNT  = 12'h010;
localparam ADDR_ENERGY      = 12'h014;
localparam ADDR_TEMP        = 12'h018;
localparam ADDR_RANK_HASH   = 12'h01C;
localparam ADDR_RANK_HASH_L = 12'h020;
localparam ADDR_RANK_HASH_H = 12'h024;
localparam ADDR_RESULT_0    = 12'h100;
localparam ADDR_RESULT_1    = 12'h104;
localparam ADDR_RESULT_2    = 12'h108;
localparam ADDR_RESULT_3    = 12'h10C;

localparam VERSION = 32'h0001_0000;

localparam CTRL_ENABLE      = 0;
localparam CTRL_START       = 1;
localparam CTRL_RESET       = 2;
localparam CTRL_IRQ_EN      = 3;

localparam STATUS_READY     = 0;
localparam STATUS_BUSY      = 1;
localparam STATUS_DONE      = 2;
localparam STATUS_ERROR     = 3;

reg [31:0] ctrl_reg;
reg [31:0] status_reg;
reg [31:0] node_count_reg;
reg [31:0] edge_count_reg;
reg [31:0] energy_reg;
reg [31:0] temp_reg;
reg [63:0] rank_hash_reg;
reg [31:0] result_regs [0:3];

reg        running;
reg [15:0] cycle_count;
reg        irq_pending;

reg [1:0]  wr_state;
localparam WR_IDLE  = 2'd0;
localparam WR_ADDR  = 2'd1;
localparam WR_DATA  = 2'd2;
localparam WR_RESP  = 2'd3;

reg [31:0] wr_addr_reg;

reg [1:0]  rd_state;
localparam RD_IDLE  = 2'd0;
localparam RD_ADDR  = 2'd1;
localparam RD_DATA  = 2'd2;

reg [31:0] rd_addr_reg;

reg [23:0] led_counter;
assign led = led_counter[23] & ctrl_reg[CTRL_ENABLE];

assign irq_out = irq_pending & ctrl_reg[CTRL_IRQ_EN];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        wr_state <= WR_IDLE;
        awready <= 1'b0;
        wready <= 1'b0;
        bvalid <= 1'b0;
        bresp <= 2'b00;
        wr_addr_reg <= 32'h0;
    end else begin
        case (wr_state)
            WR_IDLE: begin
                awready <= 1'b1;
                wready <= 1'b0;
                bvalid <= 1'b0;
                if (awvalid && awready) begin
                    wr_addr_reg <= awaddr;
                    awready <= 1'b0;
                    wr_state <= WR_DATA;
                end
            end

            WR_DATA: begin
                wready <= 1'b1;
                if (wvalid && wready) begin
                    wready <= 1'b0;
                    wr_state <= WR_RESP;
                end
            end

            WR_RESP: begin
                bvalid <= 1'b1;
                bresp <= 2'b00;
                if (bready && bvalid) begin
                    bvalid <= 1'b0;
                    wr_state <= WR_IDLE;
                end
            end

            default: wr_state <= WR_IDLE;
        endcase
    end
end

wire [31:0] wdata_masked;
assign wdata_masked = {
    wstrb[3] ? wdata[31:24] : 8'h0,
    wstrb[2] ? wdata[23:16] : 8'h0,
    wstrb[1] ? wdata[15:8]  : 8'h0,
    wstrb[0] ? wdata[7:0]   : 8'h0
};

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        ctrl_reg <= 32'h0;
        node_count_reg <= 32'h0;
        edge_count_reg <= 32'h0;
        energy_reg <= 32'h0;
        temp_reg <= 32'h00640000;
        rank_hash_reg <= 64'h0;
        result_regs[0] <= 32'h0;
        result_regs[1] <= 32'h0;
        result_regs[2] <= 32'h0;
        result_regs[3] <= 32'h0;
    end else begin

        if (ctrl_reg[CTRL_START] && running) begin
            ctrl_reg[CTRL_START] <= 1'b0;
        end

        if (ctrl_reg[CTRL_RESET]) begin
            ctrl_reg[CTRL_RESET] <= 1'b0;
            node_count_reg <= 32'h0;
            edge_count_reg <= 32'h0;
            energy_reg <= 32'h0;
        end

        if (wr_state == WR_DATA && wvalid && wready) begin
            case (wr_addr_reg[11:0])
                ADDR_CTRL: begin
                    if (wstrb[0]) ctrl_reg[7:0]   <= wdata[7:0];
                    if (wstrb[1]) ctrl_reg[15:8]  <= wdata[15:8];
                    if (wstrb[2]) ctrl_reg[23:16] <= wdata[23:16];
                    if (wstrb[3]) ctrl_reg[31:24] <= wdata[31:24];
                end

                ADDR_NODE_COUNT: begin
                    if (wstrb[0]) node_count_reg[7:0]   <= wdata[7:0];
                    if (wstrb[1]) node_count_reg[15:8]  <= wdata[15:8];
                    if (wstrb[2]) node_count_reg[23:16] <= wdata[23:16];
                    if (wstrb[3]) node_count_reg[31:24] <= wdata[31:24];
                end

                ADDR_EDGE_COUNT: begin
                    if (wstrb[0]) edge_count_reg[7:0]   <= wdata[7:0];
                    if (wstrb[1]) edge_count_reg[15:8]  <= wdata[15:8];
                    if (wstrb[2]) edge_count_reg[23:16] <= wdata[23:16];
                    if (wstrb[3]) edge_count_reg[31:24] <= wdata[31:24];
                end

                ADDR_TEMP: begin
                    if (wstrb[0]) temp_reg[7:0]   <= wdata[7:0];
                    if (wstrb[1]) temp_reg[15:8]  <= wdata[15:8];
                    if (wstrb[2]) temp_reg[23:16] <= wdata[23:16];
                    if (wstrb[3]) temp_reg[31:24] <= wdata[31:24];
                end

                ADDR_RANK_HASH_L: begin
                    if (wstrb[0]) rank_hash_reg[7:0]   <= wdata[7:0];
                    if (wstrb[1]) rank_hash_reg[15:8]  <= wdata[15:8];
                    if (wstrb[2]) rank_hash_reg[23:16] <= wdata[23:16];
                    if (wstrb[3]) rank_hash_reg[31:24] <= wdata[31:24];
                end

                ADDR_RANK_HASH_H: begin
                    if (wstrb[0]) rank_hash_reg[39:32] <= wdata[7:0];
                    if (wstrb[1]) rank_hash_reg[47:40] <= wdata[15:8];
                    if (wstrb[2]) rank_hash_reg[55:48] <= wdata[23:16];
                    if (wstrb[3]) rank_hash_reg[63:56] <= wdata[31:24];
                end

                ADDR_RESULT_0: result_regs[0] <= wdata_masked | (result_regs[0] & ~{
                    {8{wstrb[3]}}, {8{wstrb[2]}}, {8{wstrb[1]}}, {8{wstrb[0]}}
                });
                ADDR_RESULT_1: result_regs[1] <= wdata_masked | (result_regs[1] & ~{
                    {8{wstrb[3]}}, {8{wstrb[2]}}, {8{wstrb[1]}}, {8{wstrb[0]}}
                });
                ADDR_RESULT_2: result_regs[2] <= wdata_masked | (result_regs[2] & ~{
                    {8{wstrb[3]}}, {8{wstrb[2]}}, {8{wstrb[1]}}, {8{wstrb[0]}}
                });
                ADDR_RESULT_3: result_regs[3] <= wdata_masked | (result_regs[3] & ~{
                    {8{wstrb[3]}}, {8{wstrb[2]}}, {8{wstrb[1]}}, {8{wstrb[0]}}
                });
            endcase
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rd_state <= RD_IDLE;
        arready <= 1'b0;
        rvalid <= 1'b0;
        rdata <= 32'h0;
        rresp <= 2'b00;
        rd_addr_reg <= 32'h0;
    end else begin
        case (rd_state)
            RD_IDLE: begin
                arready <= 1'b1;
                rvalid <= 1'b0;
                if (arvalid && arready) begin
                    rd_addr_reg <= araddr;
                    arready <= 1'b0;
                    rd_state <= RD_DATA;
                end
            end

            RD_DATA: begin
                rvalid <= 1'b1;
                rresp <= 2'b00;

                case (rd_addr_reg[11:0])
                    ADDR_CTRL:        rdata <= ctrl_reg;
                    ADDR_STATUS:      rdata <= status_reg;
                    ADDR_VERSION:     rdata <= VERSION;
                    ADDR_NODE_COUNT:  rdata <= node_count_reg;
                    ADDR_EDGE_COUNT:  rdata <= edge_count_reg;
                    ADDR_ENERGY:      rdata <= energy_reg;
                    ADDR_TEMP:        rdata <= temp_reg;
                    ADDR_RANK_HASH:   rdata <= rank_hash_reg[31:0];
                    ADDR_RANK_HASH_L: rdata <= rank_hash_reg[31:0];
                    ADDR_RANK_HASH_H: rdata <= rank_hash_reg[63:32];
                    ADDR_RESULT_0:    rdata <= result_regs[0];
                    ADDR_RESULT_1:    rdata <= result_regs[1];
                    ADDR_RESULT_2:    rdata <= result_regs[2];
                    ADDR_RESULT_3:    rdata <= result_regs[3];
                    default:          rdata <= 32'hDEADBEEF;
                endcase

                if (rready && rvalid) begin
                    rvalid <= 1'b0;
                    rd_state <= RD_IDLE;
                end
            end

            default: rd_state <= RD_IDLE;
        endcase
    end
end

always @(*) begin
    status_reg = 32'h0;
    status_reg[STATUS_READY] = !running;
    status_reg[STATUS_BUSY] = running;
    status_reg[STATUS_DONE] = irq_pending;
    status_reg[STATUS_ERROR] = 1'b0;
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        running <= 1'b0;
        cycle_count <= 16'h0;
        irq_pending <= 1'b0;
    end else begin

        if (rd_state == RD_DATA && rd_addr_reg[11:0] == ADDR_STATUS) begin
            irq_pending <= 1'b0;
        end

        if (ctrl_reg[CTRL_START] && !running && ctrl_reg[CTRL_ENABLE]) begin
            running <= 1'b1;
            cycle_count <= 16'h0;
        end

        if (running) begin
            cycle_count <= cycle_count + 1'b1;

            if (cycle_count[3:0] == 4'hF) begin
                energy_reg <= energy_reg + 1;
            end

            if (cycle_count >= 16'd1000) begin
                running <= 1'b0;
                irq_pending <= 1'b1;
            end
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        led_counter <= 24'h0;
    end else begin
        led_counter <= led_counter + 1'b1;
    end
end

endmodule
