entry layernorm [n][d] (input: [n][d]f32) (gamma: [d]f32) (beta: [d]f32) : [n][d]f32 =
  let eps = 1e-5f32
  in map2 (\row g_b ->
    let mean = f32.sum row / f32.i64 d
    let variance = f32.sum (map (\x -> (x - mean) * (x - mean)) row) / f32.i64 d
    let std = f32.sqrt (variance + eps)
    in map3 (\x g b -> (x - mean) / std * g + b) row (g_b.0) (g_b.1)
  ) input (zip gamma beta |> replicate n)
  |> map (\row_result -> map (\x -> x) row_result)

entry layernorm_flat [m] (input: [m]f32) (gamma: [m]f32) (beta: [m]f32) : [m]f32 =
  let eps = 1e-5f32
  let mean = f32.sum input / f32.i64 m
  let variance = f32.sum (map (\x -> (x - mean) * (x - mean)) input) / f32.i64 m
  let std = f32.sqrt (variance + eps)
  in map3 (\x g b -> (x - mean) / std * g + b) input gamma beta

